// This file is automatically generated and contains metadata about this
// package deployment. It serves as a marker that this package was deployed
// using Gno Studio (or Gno Playground) and may be used by tools for analytics, verification,
// and ecosystem features.
//
// This file does not affect package execution and should not be modified.
package public_good_guide_20261008

// Package daoauth writes the arguments of a governed action as one typed,
// canonical string. memba_gov stores that string with the proposal and the
// target realm rebuilds it from its real arguments when it consumes the
// approval: the two must be equal byte for byte. Each value has exactly one
// spelling, so equal actions always encode to equal strings.
//
// Fields are joined by "|":
//
//	u:<uint64>        decimal, no sign, no leading zero
//	i:<int64>         decimal, "-" only when negative, no leading zero
//	b:0 or b:1        bool
//	a:<address>       the lowercase bech32 text the chain gives a caller
//	s:<len>:<text>    length-prefixed printable ASCII (0x20-0x7E)
//
// Strings are compared as raw bytes, with no Unicode normalisation; text is
// printable ASCII so that what a voter reads is exactly what executes.
package daoauth

import (
	"errors"
	"strconv"
	"strings"
)

const (
	MaxArgs = 1024 // bytes of one encoded argument string
	MaxText = 512  // bytes of one string field
)

var (
	ErrSyntax  = errors.New("daoauth: malformed argument string")
	ErrAddress = errors.New("daoauth: address is not lowercase bech32")
	ErrText    = errors.New("daoauth: text must be printable ASCII of at most 512 bytes")
	ErrLength  = errors.New("daoauth: arguments exceed 1024 bytes")
)

// Args accumulates fields in order. Methods panic on a value that has no
// canonical form, so a realm can never build an approval nobody can match.
type Args struct{ fields []string }

func New() *Args { return &Args{} }

func (a *Args) Uint(v uint64) *Args { return a.add("u:" + strconv.FormatUint(v, 10)) }
func (a *Args) Int(v int64) *Args   { return a.add("i:" + strconv.FormatInt(v, 10)) }

func (a *Args) Bool(v bool) *Args {
	if v {
		return a.add("b:1")
	}
	return a.add("b:0")
}

func (a *Args) Addr(v address) *Args {
	if !ValidAddress(v) {
		panic(ErrAddress.Error())
	}
	return a.add("a:" + string(v))
}

func (a *Args) Str(v string) *Args {
	if !ValidText(v) {
		panic(ErrText.Error())
	}
	return a.add("s:" + strconv.Itoa(len(v)) + ":" + v)
}

func (a *Args) add(f string) *Args {
	a.fields = append(a.fields, f)
	return a
}

// String returns the encoding. It panics past MaxArgs.
func (a *Args) String() string {
	s := strings.Join(a.fields, "|")
	if len(s) > MaxArgs {
		panic(ErrLength.Error())
	}
	return s
}

// Field is one decoded value: Tag is 'u', 'i', 'b', 'a' or 's', and Value
// is its text, without the length prefix for strings.
type Field struct {
	Tag   byte
	Value string
}

// Parse decodes s and refuses any text that is not the canonical encoding of
// its own fields. The empty string is the encoding of no fields.
func Parse(s string) ([]Field, error) {
	if len(s) > MaxArgs {
		return nil, ErrLength
	}
	var out []Field
	for len(s) > 0 {
		if len(s) < 2 || s[1] != ':' {
			return nil, ErrSyntax
		}
		tag, rest := s[0], s[2:]
		var v string
		if tag == 's' {
			i := strings.IndexByte(rest, ':')
			if i < 1 {
				return nil, ErrSyntax
			}
			n, err := strconv.Atoi(rest[:i])
			if err != nil || n < 0 || strconv.Itoa(n) != rest[:i] || n > len(rest)-i-1 {
				return nil, ErrSyntax
			}
			v, rest = rest[i+1:i+1+n], rest[i+1+n:]
			if !ValidText(v) {
				return nil, ErrText
			}
		} else {
			i := strings.IndexByte(rest, '|')
			if i < 0 {
				i = len(rest)
			}
			v, rest = rest[:i], rest[i:]
			if err := checkScalar(tag, v); err != nil {
				return nil, err
			}
		}
		out = append(out, Field{Tag: tag, Value: v})
		if len(rest) > 0 {
			if rest[0] != '|' || len(rest) == 1 {
				return nil, ErrSyntax
			}
			rest = rest[1:]
		}
		s = rest
	}
	return out, nil
}

func checkScalar(tag byte, v string) error {
	switch tag {
	case 'u':
		n, err := strconv.ParseUint(v, 10, 64)
		if err != nil || strconv.FormatUint(n, 10) != v {
			return ErrSyntax
		}
	case 'i':
		n, err := strconv.ParseInt(v, 10, 64)
		if err != nil || strconv.FormatInt(n, 10) != v {
			return ErrSyntax
		}
	case 'b':
		if v != "0" && v != "1" {
			return ErrSyntax
		}
	case 'a':
		if !ValidAddress(address(v)) {
			return ErrAddress
		}
	default:
		return ErrSyntax
	}
	return nil
}

// ValidText reports whether s is at most MaxText bytes of printable ASCII
// (0x20 to 0x7E): no control, invisible, combining or direction-changing
// character can make a value read differently from what executes.
func ValidText(s string) bool {
	if len(s) > MaxText {
		return false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < 0x20 || s[i] > 0x7e {
			return false
		}
	}
	return true
}

// The chain decodes four texts to one address: the lowercase bech32 text it
// gives a caller, that text in capitals, and the bech32m checksum in either
// case. Only the first ever equals cur.Previous().Address(). The check below
// is the one of launchpad meta/v1, copied rather than imported so governance
// does not depend on the Launchpad release. It reads the text instead of
// decoding it.

// bech32Value holds, for each character of the bech32 alphabet, its 5-bit
// value plus one. Zero marks every other byte, capitals included.
var bech32Value = [256]byte{
	'q': 1, 'p': 2, 'z': 3, 'r': 4, 'y': 5, '9': 6, 'x': 7, '8': 8,
	'g': 9, 'f': 10, '2': 11, 't': 12, 'v': 13, 'd': 14, 'w': 15, '0': 16,
	's': 17, '3': 18, 'j': 19, 'n': 20, '5': 21, '4': 22, 'k': 23, 'h': 24,
	'c': 25, 'e': 26, '6': 27, 'm': 28, 'u': 29, 'a': 30, '7': 31, 'l': 32,
}

// bech32Gen[t] is the XOR of the BIP-173 generators selected by the bits of t.
var bech32Gen = [32]uint32{
	0x00000000, 0x3b6a57b2, 0x26508e6d, 0x1d3ad9df,
	0x1ea119fa, 0x25cb4e48, 0x38f19797, 0x039bc025,
	0x3d4233dd, 0x0628646f, 0x1b12bdb0, 0x2078ea02,
	0x23e32a27, 0x18897d95, 0x05b3a44a, 0x3ed9f3f8,
	0x2a1462b3, 0x117e3501, 0x0c44ecde, 0x372ebb6c,
	0x34b57b49, 0x0fdf2cfb, 0x12e5f524, 0x298fa296,
	0x1756516e, 0x2c3c06dc, 0x3106df03, 0x0a6c88b1,
	0x09f74894, 0x329d1f26, 0x2fa7c6f9, 0x14cd914b,
}

// bech32PrefixState is the checksum state after the prefix "g" (3, 0, 7).
const bech32PrefixState uint32 = 0x8c07

// ValidAddress reports whether a is "g1" and 38 lowercase bech32 characters
// whose checksum is the original bech32 one.
func ValidAddress(a address) bool {
	s := string(a)
	if len(s) != 40 || s[0] != 'g' || s[1] != '1' {
		return false
	}
	chk := bech32PrefixState
	for i := 2; i < 40; i++ {
		v := bech32Value[s[i]]
		if v == 0 {
			return false
		}
		chk = (chk&0x1ffffff)<<5 ^ uint32(v-1) ^ bech32Gen[chk>>25]
	}
	return chk == 1
}

// Package memba_gov is the Memba DAO governance core. It holds the roster,
// proposals and votes, and grants nothing by itself: a governed realm asks
// for an approval by crossing-calling Consume before a privileged step, and
// the core checks that the caller is exactly the realm the proposal names,
// with exactly the arguments members voted on. The core never calls another
// realm.
//
// Rules (design note GOV-1, approved 2026-10-06):
//   - members propose, vote and execute by direct calls from their own
//     account, and an invited key joins by its own direct call; only a
//     governed realm's crossing call reaches Consume;
//   - a key counts toward the roster only after it signed Join itself;
//   - one action per proposal, stored by value; approvals are used once;
//   - every executed roster action and every Join invalidates every open
//     proposal, so votes always count against an unchanged roster;
//   - Consume invalidates the other open proposals of its (target, scope).
package memba_gov

import (
	"strconv"
	"strings"
	"time"

	"gno.land/p/samcrew/avl"
	"gno.land/p/samcrew/daoauth"
)

const (
	corePath  = "gno.land/r/samcrew/memba_gov"
	MaxSeats  = 25
	MinSeats  = 2
	MaxScope  = 160
	MaxNote   = 280
	MaxAction = 64

	actAddMember      = "AddMember"
	actRemoveMember   = "RemoveMember"
	actSetWeight      = "SetWeight"
	actRecover        = "Recover"
	actRemoveInactive = "RemoveInactive"
	actUninvite       = "Uninvite"

	voteYes     = "yes"
	voteNo      = "no"
	voteAbstain = "abstain"
)

type person struct {
	id         string
	addr       address
	weight     int
	lastActive int64  // unix seconds of the last Propose, Vote, Execute or Join
	rosterPid  uint64 // this person's open roster proposal, if any
}

// invite seats addr as id (a new person) or, for a recovery, gives the
// existing person id the new key addr, once addr itself calls Join.
type invite struct {
	id      string
	addr    address
	weight  int
	expires int64 // unix seconds
}

type ballot struct {
	person string
	vote   string
	since  int64 // unix start of the current uninterrupted YES streak
}

type proposal struct {
	id                    uint64
	target, action, args  string
	scope, note, proposer string
	subject               string // the person a roster action names
	class                 int
	scopeGen, globalGen   uint64
	created               int64 // unix seconds
	ballots               []ballot
	consumed              bool
}

var (
	seated    []*person
	invites   []*invite
	proposals = avl.NewTree() // padded id -> *proposal
	scopes    = avl.NewTree() // target + "\n" + scope -> uint64 generation
	lastID    uint64
	globalGen uint64
)

func init() { seedRoster() }

func seedRoster() {
	t := now()
	for _, s := range seedSeated {
		seated = append(seated, &person{id: s.id, addr: s.addr, weight: s.weight, lastActive: t})
	}
	for _, s := range seedInvited {
		invites = append(invites, &invite{id: s.id, addr: s.addr, weight: s.weight, expires: t + secs(SeedInviteTTL)})
	}
	checkRoster()
}

// now is the block time in unix seconds; every stored time uses it.
func now() int64 { return time.Now().Unix() }

func secs(d time.Duration) int64 { return int64(d / time.Second) }

// ── Writes (direct calls from a member's account) ──────────────────────

// Propose files one action. target is the realm that will consume it, or
// this realm for a roster action; scope is the invalidation key that realm
// computes for the action; class is at least the class it requires.
func Propose(cur realm, target, action, args, scope string, class int, note string) uint64 {
	m := member(cur)
	if !validTarget(target) || !validAction(action) || len(scope) > MaxScope || len(note) > MaxNote ||
		!daoauth.ValidText(scope) || !daoauth.ValidText(note) {
		panic("memba_gov: invalid target, action, scope or note")
	}
	fields, err := daoauth.Parse(args)
	if err != nil {
		panic(err.Error())
	}
	if target == corePath {
		if scope != "" || class != rosterClass(action) {
			panic("memba_gov: a roster action has no scope and a fixed class")
		}
		checkRosterAction(action, fields)
		if m.rosterPid != 0 && isOpen(m.rosterPid) {
			panic("memba_gov: you already have an open roster proposal")
		}
	} else if class < Routine || class > Critical {
		panic("memba_gov: unknown class")
	}
	lastID++
	p := &proposal{id: lastID, target: target, action: action, args: args, scope: scope, note: note,
		proposer: m.id, class: class, scopeGen: scopeGen(target, scope), globalGen: globalGen, created: now()}
	proposals.Set(key(p.id), p)
	if target == corePath {
		p.subject = fields[0].Value
		m.rosterPid = p.id
	}
	m.lastActive = p.created
	return p.id
}

// Vote records yes, no or abstain until the voting deadline. After it, a
// YES can still be withdrawn while the proposal is not executed or expired,
// so members can stop an approval they no longer back.
func Vote(cur realm, pid uint64, choice string) {
	m := member(cur)
	if choice != voteYes && choice != voteNo && choice != voteAbstain {
		panic("memba_gov: vote yes, no or abstain")
	}
	p := mustGet(pid)
	t := now()
	mine := -1
	for i, b := range p.ballots {
		if b.person == m.id {
			mine = i
		}
	}
	st, _ := state(p)
	open := st == stVoting || st == stTimelocked || st == stReady
	withdrawing := mine >= 0 && p.ballots[mine].vote == voteYes && choice != voteYes
	if !open || (t >= p.created+secs(VotingPeriod) && !withdrawing) {
		panic("memba_gov: voting is closed")
	}
	m.lastActive = t
	switch {
	case mine < 0:
		p.ballots = append(p.ballots, ballot{person: m.id, vote: choice, since: t})
	case p.ballots[mine].vote != choice:
		p.ballots[mine] = ballot{person: m.id, vote: choice, since: t}
	}
}

// Join seats the caller's invitation: a new person, or a recovered key.
func Join(cur realm) {
	addr := user(cur)
	t := now()
	for i, inv := range invites {
		if inv.addr != addr || t > inv.expires {
			continue
		}
		invites = append(invites[:i:i], invites[i+1:]...)
		if p := personByID(inv.id); p != nil {
			p.addr = addr
			p.lastActive = t
		} else {
			if len(seated) >= MaxSeats {
				panic("memba_gov: the roster is full (" + strconv.Itoa(MaxSeats) + " seats)")
			}
			seated = append(seated, &person{id: inv.id, addr: addr, weight: inv.weight, lastActive: t})
		}
		globalGen++
		checkRoster()
		return
	}
	panic("memba_gov: no open invitation for " + string(addr))
}

// Execute runs a ready roster action of this realm. The roster it was
// checked against at Propose is unchanged: any change would have
// invalidated it.
func Execute(cur realm, pid uint64) {
	m := member(cur)
	p := mustGet(pid)
	if p.target != corePath {
		panic("memba_gov: only roster actions run here; the target realm consumes the others")
	}
	if st, _ := state(p); st != stReady {
		panic("memba_gov: proposal is " + st)
	}
	fields, _ := daoauth.Parse(p.args)
	id := p.subject
	switch p.action {
	case actAddMember:
		addInvite(id, address(fields[1].Value), weightField(fields[2]), VotedInviteTTL)
	case actRecover:
		addInvite(id, address(fields[1].Value), 0, VotedInviteTTL)
	case actSetWeight:
		personByID(id).weight = weightField(fields[1])
	case actRemoveMember, actRemoveInactive, actUninvite:
		removePerson(id)
	}
	p.consumed = true
	m.lastActive = now()
	globalGen++
	checkRoster()
}

// ── The only cross-realm entry ──────────────────────────────────────────

// Consume is crossing-called by a governed realm right before the step a
// proposal approved. It panics unless the caller is exactly the proposal's
// target, the action, arguments and scope are the voted ones byte for byte,
// the class is at least minClass, the proposal is ready, and executor, the
// account that called the target directly, is a seated member. It marks the
// proposal used and invalidates the other open proposals of (target, scope).
func Consume(cur realm, pid uint64, action, args, scope string, minClass int, executor address) {
	if !cur.IsCurrent() {
		panic("memba_gov: stale realm")
	}
	caller := cur.Previous().PkgPath()
	p := mustGet(pid)
	// A roster action runs only through Execute.
	if caller != p.target || p.target == corePath {
		panic("memba_gov: proposal " + strconv.FormatUint(pid, 10) + " is not for " + caller)
	}
	if action != p.action || args != p.args || scope != p.scope {
		panic("memba_gov: action, arguments or scope differ from the vote")
	}
	if p.class < minClass {
		panic("memba_gov: class below what the target requires")
	}
	if st, _ := state(p); st != stReady {
		panic("memba_gov: proposal is " + st)
	}
	// Being named executor is not activity: the target, not the member,
	// supplies that address.
	if personByAddr(executor) == nil {
		panic("memba_gov: executor is not a seated member")
	}
	p.consumed = true
	scopes.Set(p.target+"\n"+p.scope, scopeGen(p.target, p.scope)+1)
}

// IsMember reports whether addr is a seated member's current key.
func IsMember(addr address) bool { return personByAddr(addr) != nil }

// PersonOf returns the id of the seated member whose current key is addr,
// or "". The id survives a key recovery.
func PersonOf(addr address) string {
	if p := personByAddr(addr); p != nil {
		return p.id
	}
	return ""
}

// ── Helpers ─────────────────────────────────────────────────────────────

// user returns the account that called this realm directly.
func user(cur realm) address {
	if !cur.IsCurrent() {
		panic("memba_gov: stale realm")
	}
	prev := cur.Previous()
	if !prev.IsUserCall() {
		panic("memba_gov: call directly from your account")
	}
	return prev.Address()
}

func member(cur realm) *person {
	addr := user(cur)
	m := personByAddr(addr)
	if m == nil {
		panic("memba_gov: not a seated member: " + string(addr))
	}
	return m
}

// rosterClass and rosterDelay fix how each roster action passes.
func rosterClass(action string) int {
	switch action {
	case actRemoveInactive:
		return Routine
	case actUninvite: // fast for a leaked invitee key, never a two-person lever
		return Financial
	}
	return Critical
}

func rosterDelay(action string) time.Duration {
	switch action {
	case actUninvite:
		return 0
	case actRemoveInactive:
		return InactiveDelay
	}
	return RosterDelay
}

// checkRosterAction validates a roster action's fields against the roster.
func checkRosterAction(action string, f []daoauth.Field) {
	shape := map[string]string{actAddMember: "sau", actRemoveMember: "s", actSetWeight: "su",
		actRecover: "sa", actRemoveInactive: "s", actUninvite: "s"}[action]
	if shape == "" || len(f) != len(shape) {
		panic("memba_gov: unknown roster action or wrong arguments")
	}
	for i := range f {
		if f[i].Tag != shape[i] {
			panic("memba_gov: wrong roster arguments")
		}
	}
	id := f[0].Value
	p := personByID(id)
	switch action {
	case actAddMember, actUninvite:
		if p != nil || !validID(id) {
			panic("memba_gov: person id taken or invalid")
		}
	default:
		if p == nil {
			panic("memba_gov: no seated person " + id)
		}
	}
	switch action {
	case actAddMember, actRecover:
		if addrTaken(address(f[1].Value), id) {
			panic("memba_gov: address already seated or invited")
		}
	case actUninvite:
		if !invited(id) {
			panic("memba_gov: no open invitation for " + id)
		}
	case actRemoveMember, actRemoveInactive:
		if len(seated) <= MinSeats {
			panic("memba_gov: the roster cannot shrink below " + strconv.Itoa(MinSeats))
		}
	}
	if action == actAddMember {
		weightField(f[2])
	}
	if action == actSetWeight && weightField(f[1]) == p.weight {
		panic("memba_gov: weight unchanged")
	}
	if action == actRemoveInactive && now() <= p.lastActive+secs(InactiveAfter) {
		panic("memba_gov: active within " + strconv.Itoa(int(secs(InactiveAfter)/86400)) + " days")
	}
}

func weightField(f daoauth.Field) int {
	if f.Value != "1" && f.Value != "2" {
		panic("memba_gov: weight is 1 or 2")
	}
	return int(f.Value[0] - '0')
}

func addInvite(id string, addr address, weight int, ttl time.Duration) {
	dropInvite(id)
	invites = append(invites, &invite{id: id, addr: addr, weight: weight, expires: now() + secs(ttl)})
}

func dropInvite(id string) {
	kept := invites[:0:0]
	for _, inv := range invites {
		if inv.id != id {
			kept = append(kept, inv)
		}
	}
	invites = kept
}

func removePerson(id string) {
	kept := seated[:0:0]
	for _, p := range seated {
		if p.id != id {
			kept = append(kept, p)
		}
	}
	seated = kept
	dropInvite(id)
}

// checkRoster enforces the bounds, valid ids, addresses and weights, and the
// uniqueness of ids and of addresses across seats and open invitations. An
// invitation may name a seated id: that is a recovery, with no weight.
func checkRoster() {
	if len(seated) < MinSeats || len(seated) > MaxSeats {
		panic("memba_gov: roster size out of bounds")
	}
	seen := map[string]bool{}
	for _, p := range seated {
		if seen["i"+p.id] || seen["a"+string(p.addr)] || !validID(p.id) || !daoauth.ValidAddress(p.addr) || p.weight < 1 || p.weight > 2 {
			panic("memba_gov: invalid roster")
		}
		seen["i"+p.id], seen["a"+string(p.addr)] = true, true
	}
	t := now()
	for _, inv := range invites {
		if t > inv.expires {
			continue
		}
		recovery := personByID(inv.id) != nil
		if seen["v"+inv.id] || seen["a"+string(inv.addr)] || !validID(inv.id) || !daoauth.ValidAddress(inv.addr) ||
			(!recovery && (inv.weight < 1 || inv.weight > 2)) {
			panic("memba_gov: invalid invitation")
		}
		seen["v"+inv.id], seen["a"+string(inv.addr)] = true, true
	}
}

// addrTaken reports whether a is seated, or invited for someone other than
// id: a newer invitation for id replaces id's own.
func addrTaken(a address, id string) bool {
	if personByAddr(a) != nil {
		return true
	}
	for _, inv := range invites {
		if inv.addr == a && inv.id != id && now() <= inv.expires {
			return true
		}
	}
	return false
}

func invited(id string) bool {
	for _, inv := range invites {
		if inv.id == id && now() <= inv.expires {
			return true
		}
	}
	return false
}

func personByAddr(a address) *person {
	for _, p := range seated {
		if p.addr == a {
			return p
		}
	}
	return nil
}

func personByID(id string) *person {
	for _, p := range seated {
		if p.id == id {
			return p
		}
	}
	return nil
}

func weightOf(id string) int {
	if p := personByID(id); p != nil {
		return p.weight
	}
	return 0
}

func seatedTotals() (w, n int) {
	for _, p := range seated {
		w += p.weight
	}
	return w, len(seated)
}

func scopeGen(target, scope string) uint64 {
	if v, ok := scopes.Get(target + "\n" + scope); ok {
		return v.(uint64)
	}
	return 0
}

func isOpen(pid uint64) bool {
	st, _ := state(mustGet(pid))
	return st == stVoting || st == stTimelocked || st == stReady
}

func mustGet(pid uint64) *proposal {
	v, ok := proposals.Get(key(pid))
	if !ok {
		panic("memba_gov: no proposal " + strconv.FormatUint(pid, 10))
	}
	return v.(*proposal)
}

func key(id uint64) string {
	s := strconv.FormatUint(id, 10)
	return strings.Repeat("0", 20-len(s)) + s
}

// validTarget accepts a realm path: no user ("") or MsgRun (gno.land/e/)
// identity, no sub-realm ("#"), lowercase path characters only.
func validTarget(t string) bool {
	return strings.HasPrefix(t, "gno.land/r/") && len(t) <= 256 && !strings.Contains(t, "//") &&
		!strings.HasSuffix(t, "/") && only(t, lower+digits+"_/.")
}

func validAction(a string) bool {
	return a != "" && len(a) <= MaxAction && only(a, lower+upper+digits+"_.")
}

func validID(id string) bool { return id != "" && len(id) <= 32 && only(id, lower+digits+"_-") }

const (
	lower  = "abcdefghijklmnopqrstuvwxyz"
	upper  = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
	digits = "0123456789"
)

// only reports whether every byte of s is in set.
func only(s, set string) bool {
	for i := 0; i < len(s); i++ {
		if strings.IndexByte(set, s[i]) < 0 {
			return false
		}
	}
	return true
}

package memba_gov

import "time"

// Classes. A target hard-codes the minimum class of each action it governs.
const (
	Routine   = 1
	Financial = 2
	Critical  = 3
)

// A route is one way a proposal passes: a rule on the YES votes of the
// seated roster and the delay that follows. Thresholds are fractions of the
// seated weight W and persons N. Every rule needs at least two persons: the
// critical ones because N is at least 2.
type route struct {
	rule  int
	delay time.Duration
}

const (
	ruleRoutine = iota
	ruleFinancial
	ruleWeighted
	ruleHeadcount
)

func meets(rule, w, p, W, N int) bool {
	switch rule {
	case ruleRoutine: // >= 3/8 of the weight
		return 8*w >= 3*W && p >= 2
	case ruleFinancial: // >= 3/5 of the weight and a majority of persons
		return 5*w >= 3*W && p >= 3 && 2*p > N
	case ruleWeighted: // >= 2/3 of the weight and a majority of persons
		return 3*w >= 2*W && 2*p > N
	case ruleHeadcount: // >= 2/3 of the persons and a majority of the weight
		return 3*p >= 2*N && 2*w > W
	}
	return false
}

// routes returns the ways proposal p passes: its class sets the rules, and
// a roster action of this realm has its own delay on every route.
func routes(p *proposal) []route {
	var rs []route
	switch p.class {
	case Routine:
		rs = []route{{ruleRoutine, 0}}
	case Financial:
		rs = []route{{ruleFinancial, 0}}
	default:
		rs = []route{{ruleWeighted, WeightedDelay}, {ruleHeadcount, HeadcountDelay}}
	}
	if p.target == corePath {
		for i := range rs {
			rs[i].delay = rosterDelay(p.action)
		}
	}
	return rs
}

// A streak is one current YES ballot: when it began and its voter's weight.
type streak struct {
	since  int64
	weight int
}

// yesStreaks returns p's current YES ballots, oldest streak first.
func yesStreaks(p *proposal) []streak {
	var ys []streak
	for _, b := range p.ballots {
		if b.vote != voteYes {
			continue
		}
		x := streak{b.since, weightOf(b.person)}
		ys = append(ys, x)
		i := len(ys) - 1
		for ; i > 0 && ys[i-1].since > x.since; i-- {
			ys[i] = ys[i-1]
		}
		ys[i] = x
	}
	return ys
}

// qualifiedSince returns when (unix seconds) the earliest coalition still
// voting YES without interruption first met rule, or 0. The coalition of a
// start time is every YES streak begun no later; every rule only grows with
// more votes, so the first prefix of ys that meets it ends on that time
// (streaks begun in the same second share it). A voter the rest of the
// coalition does not need cannot postpone the clock by withdrawing and
// rejoining.
func qualifiedSince(ys []streak, rule, W, N int) int64 {
	w, n := 0, 0
	for _, x := range ys {
		w += x.weight
		n++
		if meets(rule, w, n, W, N) {
			return x.since
		}
	}
	return 0
}

// Proposal states, in the order a reader checks them.
const (
	stExecuted    = "executed"
	stInvalidated = "invalidated"
	stExpired     = "expired"
	stReady       = "ready"
	stTimelocked  = "timelocked"
	stVoting      = "voting"
)

// state returns p's status and, once some route qualified, the earliest
// unix time it is or becomes executable (0 before). Voting ends just before
// the deadline second; readyAt and the end of the execution window are
// inclusive.
func state(p *proposal) (string, int64) {
	if p.consumed {
		return stExecuted, 0
	}
	if p.globalGen != globalGen || p.scopeGen != scopeGen(p.target, p.scope) || vetoed(p) {
		return stInvalidated, 0
	}
	t := now()
	W, N := seatedTotals()
	ys := yesStreaks(p)
	var readyAt, longest int64
	for _, r := range routes(p) {
		if d := secs(r.delay); d > longest {
			longest = d
		}
		if since := qualifiedSince(ys, r.rule, W, N); since != 0 {
			if at := since + secs(r.delay); readyAt == 0 || at < readyAt {
				readyAt = at
			}
		}
	}
	deadline := p.created + secs(VotingPeriod)
	if t > deadline+longest+secs(ExecutionWindow) || (readyAt == 0 && t >= deadline) {
		return stExpired, readyAt
	}
	switch {
	case readyAt == 0:
		return stVoting, readyAt
	case t < readyAt:
		return stTimelocked, readyAt
	}
	return stReady, readyAt
}

// vetoed reports whether the member a RemoveInactive names has been active
// since the proposal: proposing, voting, executing or joining vetoes it.
func vetoed(p *proposal) bool {
	if p.target != corePath || p.action != actRemoveInactive {
		return false
	}
	m := personByID(p.subject)
	return m != nil && m.lastActive >= p.created
}

package memba_gov

import (
	"strconv"
	"time"
)

// Reads make no cross-realm call and never start or advance a clock. Ids and
// unix times are JSON strings (clients parse them as big integers). Stored
// text is printable ASCII, so the escapers work byte by byte.

// MaxListed is the most proposals ProposalsJSON and Render return at once.
const MaxListed = 20

// RosterJSON lists seated members and open invitations.
func RosterJSON() string {
	W, N := seatedTotals()
	b := []byte(`{"weight":` + strconv.Itoa(W) + `,"persons":` + strconv.Itoa(N) + `,"members":[`)
	for i, p := range seated {
		if i > 0 {
			b = append(b, ',')
		}
		b = append(b, `{"id":`...)
		b = q(b, p.id)
		b = append(b, `,"address":`...)
		b = q(b, string(p.addr))
		b = append(b, `,"weight":`+strconv.Itoa(p.weight)+`,"lastActive":"`+unix(p.lastActive)+`"}`...)
	}
	b = append(b, `],"invitations":[`...)
	n := 0
	for _, inv := range invites {
		if now() > inv.expires {
			continue
		}
		if n > 0 {
			b = append(b, ',')
		}
		n++
		b = append(b, `{"id":`...)
		b = q(b, inv.id)
		b = append(b, `,"address":`...)
		b = q(b, string(inv.addr))
		b = append(b, `,"weight":`+strconv.Itoa(inv.weight)+`,"expires":"`+unix(inv.expires)+`"}`...)
	}
	return string(append(b, `]}`...))
}

// ProposalJSON returns one proposal with its ballots and current status, or
// null for an unknown id.
func ProposalJSON(pid uint64) string {
	v, ok := proposals.Get(key(pid))
	if !ok {
		return "null"
	}
	return string(proposalJSON(nil, v.(*proposal)))
}

// ConstantsJSON returns the fixed policy: durations in seconds, roster bounds.
func ConstantsJSON() string {
	sec := func(d time.Duration) string { return unix(secs(d)) }
	return `{"votingPeriod":` + sec(VotingPeriod) + `,"executionWindow":` + sec(ExecutionWindow) +
		`,"criticalWeightDelay":` + sec(WeightedDelay) + `,"criticalHeadcountDelay":` + sec(HeadcountDelay) +
		`,"rosterDelay":` + sec(RosterDelay) + `,"inactiveDelay":` + sec(InactiveDelay) +
		`,"inactiveAfter":` + sec(InactiveAfter) + `,"minSeats":` + strconv.Itoa(MinSeats) +
		`,"maxSeats":` + strconv.Itoa(MaxSeats) + `,"maxListed":` + strconv.Itoa(MaxListed) + `}`
}

// ProposalsJSON lists up to limit proposals (at most MaxListed) with ids
// below before, newest first; before = 0 starts from the newest.
func ProposalsJSON(before uint64, limit int) string {
	if limit < 1 || limit > MaxListed {
		limit = MaxListed
	}
	b := []byte(`{"total":"` + strconv.FormatUint(lastID, 10) + `","proposals":[`)
	if before != 1 {
		end := "" // a descending range includes its end
		if before > 1 {
			end = key(before - 1)
		}
		n := 0
		proposals.ReverseIterate("", end, func(_ string, v any) bool {
			if n > 0 {
				b = append(b, ',')
			}
			b = proposalJSON(b, v.(*proposal))
			n++
			return n >= limit
		})
	}
	return string(append(b, `]}`...))
}

func proposalJSON(b []byte, p *proposal) []byte {
	st, readyAt := state(p)
	b = append(b, `{"id":"`+strconv.FormatUint(p.id, 10)+`","target":`...)
	b = q(b, p.target)
	b = append(b, `,"action":`...)
	b = q(b, p.action)
	b = append(b, `,"args":`...)
	b = q(b, p.args)
	b = append(b, `,"scope":`...)
	b = q(b, p.scope)
	b = append(b, `,"class":`+strconv.Itoa(p.class)+`,"proposer":`...)
	b = q(b, p.proposer)
	b = append(b, `,"note":`...)
	b = q(b, p.note)
	b = append(b, `,"created":"`+unix(p.created)+`","deadline":"`+unix(p.created+secs(VotingPeriod))+
		`","status":"`+st+`","readyAt":"`+unix(readyAt)+`","ballots":[`...)
	for i, bl := range p.ballots {
		if i > 0 {
			b = append(b, ',')
		}
		b = append(b, `{"person":`...)
		b = q(b, bl.person)
		b = append(b, `,"vote":"`+bl.vote+`","since":"`+unix(bl.since)+`"}`...)
	}
	return append(b, `]}`...)
}

// Render shows the roster and the latest proposals. Each proposal's line
// holds only fields the realm sets (id, status, class, proposer id); every
// value a proposer wrote follows as its own labelled, escaped item, so none
// can forge a field.
func Render(_ string) string {
	W, N := seatedTotals()
	b := []byte("# Memba DAO governance\n\n## Members: " + strconv.Itoa(N) + " seated, weight " + strconv.Itoa(W) + "\n\n")
	for _, p := range seated {
		b = append(b, "- "...)
		b = md(b, p.id)
		b = append(b, " (weight "+strconv.Itoa(p.weight)+"): "...)
		b = md(b, string(p.addr))
		b = append(b, '\n')
	}
	b = append(b, "\n## Latest proposals\n\n"...)
	n := 0
	proposals.ReverseIterate("", "", func(_ string, v any) bool {
		p := v.(*proposal)
		st, _ := state(p)
		b = append(b, "- #"+strconv.FormatUint(p.id, 10)+" "+st+", class "+strconv.Itoa(p.class)+", by "...)
		b = md(b, p.proposer)
		b = append(b, '\n')
		for _, f := range [][2]string{{"target", p.target}, {"action", p.action}, {"args", p.args}, {"scope", p.scope}, {"proposer's note", p.note}} {
			if f[1] != "" {
				b = append(b, "  - "+f[0]+": "...)
				b = md(b, f[1])
				b = append(b, '\n')
			}
		}
		n++
		return n >= MaxListed
	})
	if n == 0 {
		b = append(b, "None yet.\n"...)
	}
	return string(b)
}

// unix formats a unix-second time (0 = none).
func unix(t int64) string { return strconv.FormatInt(t, 10) }

// grow makes room for n more bytes. The VM's append reallocates to the exact
// length, so appending byte by byte past capacity would copy the whole
// buffer each time; doubling keeps the escapers linear.
func grow(b []byte, n int) []byte {
	if cap(b)-len(b) >= n {
		return b
	}
	nb := make([]byte, len(b), 2*cap(b)+n)
	copy(nb, b)
	return nb
}

// Escaper classes of each ASCII byte, one table lookup per byte: '.' is
// copied, 'b' gets a backslash, 'u' becomes \u00XX, 'e' a numeric
// character reference. Stored text is printable ASCII (0x7f masks the
// index; no other byte reaches here).
const (
	qClass = "uuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuu" +
		"..b...u.....................u.u." +
		"............................b..." +
		"...............................u"
	// Markdown punctuation is backslash-escaped; < > & and g become
	// references, so no HTML, entity or " g1..." address mention (a gnoweb
	// user link) can form.
	mdClass = "eeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee" +
		".bbbb.ebbbbb.bbb..........b.ebe." +
		"b..........................bbbbb" +
		"b......e...................bbbbe"
	hexDigits = "0123456789abcdef"
)

// q appends s as a JSON string; < > & are escaped so the text stays inert
// in HTML.
func q(b []byte, s string) []byte {
	b = grow(b, 6*len(s)+2)
	b = append(b, '"')
	for i := 0; i < len(s); i++ {
		switch c := s[i]; qClass[c&0x7f] {
		case '.':
			b = append(b, c)
		case 'b':
			b = append(b, '\\', c)
		default:
			b = append(b, '\\', 'u', '0', '0', hexDigits[c>>4], hexDigits[c&0xf])
		}
	}
	return append(b, '"')
}

// md appends s with every character Markdown, HTML or gnoweb could act on
// made literal.
func md(b []byte, s string) []byte {
	b = grow(b, 6*len(s))
	for i := 0; i < len(s); i++ {
		switch c := s[i]; mdClass[c&0x7f] {
		case '.':
			b = append(b, c)
		case 'b':
			b = append(b, '\\', c)
		default: // &#NN; or &#NNN;
			b = append(b, '&', '#')
			if c >= 100 {
				b = append(b, '0'+c/100)
			}
			b = append(b, '0'+c/10%10, '0'+c%10, ';')
		}
	}
	return b
}

