	out := ""
	out += md.H1("NightSky - Recent Captures")

	if recentCaptures.Len() == 0 {
		out += "\nNo captures yet.\n\n"
		out += md.Link("← Back to main page", "/r/nym-vikbez000/nightsky/v1") + "\n\n"
		return out
